-- 1407: место в парке — связью по контуру, а не по имени: закрытие парка
--       доходит до каждого места внутри его границы.
-- Created: 2026-11-08
--
-- ── Почему ───────────────────────────────────────────────────────────────
--
-- 08.11, межсезонье: сводка «Вулканы Камчатки» закрыла туристические
-- маршруты на всех территориях природных парков. get_guardian_context с
-- прода: «Вулкан Авачинский» — КРАСНЫЙ, а Корякская сопка, Жупановский и
-- Таловские горячие источники — ЗЕЛЁНЫЕ. Все четыре — внутри контура
-- «Налычево»: так их нашла миграция 1248 (точка в контуре отношения OSM
-- 3978019) и записала им режим парка с разрешением. Правило закрытия
-- (PARK_SCOPED_SQL, lib/services/safety/alert-place-scope.ts) знало пять
-- путей «в парке» — имя места, маршрут с записанным парком, путевая точка
-- такого маршрута, имя места в названии маршрута и наоборот — и ни одного по
-- контуру. У маршрутов на Корякскую сопку парк не записан, и сопка стояла
-- зелёной при закрытом парке. Расхождение первым показал внешний ИИ-агент
-- (Qwen) — на скрытой записи «Авачинский вулкан: путь на вершину»; сверка
-- остальных мест парка нашла сопку и ещё двоих.
--
-- Принадлежность по контуру уже установлена — списками id в миграциях
-- парков. Не было места, где она лежит связью «место — парк» и откуда её
-- читает правило закрытия. Эта таблица — такое место; правило читает её
-- шестым путём.
--
-- ── Что в связях — только проверенное точкой в контуре ────────────────────
--
--   nalychevo (отношение OSM 3978019): 20 мест с режимом парка и 3 места зоны
--     свободного посещения (1248), кордон «Авачинский» и сейсмостанция (1289) —
--     все 25, что 1248 насчитала внутри;
--   bystrinskiy (отношение OSM 21624152): 22 места (1246). Две точки в самом
--     Эссо — горячие источники и Шаманская поляна — внутри контура, но связи
--     не получают: 1246 и 1289 не решили, действует ли режим парка на улице
--     райцентра, а закрытие маршрутов парка село не закрывает;
--   klyuchevskoy (отношение OSM 21624151): 40 мест (1245);
--   yuzhno-kamchatsky (отношение OSM 21624150): 7 мест (1245). Полноту контура
--     подтвердить нечем — связь только добавляет: место без связи не значит
--     «не в парке»;
--   vilyuchinsky (OSM way 1445902160): 4 места (1254);
--   kronotsky (отношение OSM 2800189): 5 мест (1274) и 21 (1289);
--   komandorskiy: Арка Стеллера (1288) и 2 места (1289, отношения 5576397 и
--     1962840).
--
-- Карточкам самих парков связь не нужна: их имя называет парк, и правило
-- находит их первым путём. Заказники и памятники природы сюда не входят:
-- закрытие парка их не называет.
--
-- place_id — TEXT без FK, как в place_volcano_links (1029): places.id на
-- проде TEXT. Связь ложится, только если есть и место, и парк в справочнике;
-- повтор — без изменений. Строки мест эта миграция не меняет.
--
-- Новая партия парка «по контуру» пишет связи сама, тем же INSERT.
--
-- ПОСЛЕ ВЫКАТА: статус мест пересчитает ближайший прогон safety-ingest;
-- пакетов карты связь не касается.
--
-- IDEMPOTENT

BEGIN;

CREATE TABLE IF NOT EXISTS place_park_links (
  place_id   TEXT        NOT NULL,
  park_slug  VARCHAR(64) NOT NULL REFERENCES parks (slug),
  -- Чем установлено, что место внутри парка, — словами. Пустой причины не бывает.
  reason     TEXT        NOT NULL CHECK (length(trim(reason)) > 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (place_id, park_slug)
);

CREATE INDEX IF NOT EXISTS idx_place_park_links_park ON place_park_links (park_slug);

