INSERT INTO place_park_links (place_id, park_slug, reason)
SELECT w.place_id, w.park_slug, w.reason
  FROM wanted w
  JOIN places p ON p.id::text = w.place_id::text
  JOIN parks pk ON pk.slug = w.park_slug
ON CONFLICT (place_id, park_slug) DO NOTHING;

-- ── Исход называется вслух ────────────────────────────────────────────────
-- Не легла связь — не молчим: места нет или парка нет в справочнике (§4.0).
DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT e.slug, e.expected, COUNT(l.place_id)::int AS got
      FROM (VALUES ('nalychevo', 25), ('bystrinskiy', 22), ('klyuchevskoy', 40),
                   ('yuzhno-kamchatsky', 7), ('vilyuchinsky', 4), ('kronotsky', 26),
                   ('komandorskiy', 3)) AS e(slug, expected)
      LEFT JOIN place_park_links l ON l.park_slug = e.slug
     GROUP BY e.slug, e.expected
     ORDER BY e.slug
  LOOP
    IF r.got < r.expected THEN
      RAISE WARNING '[1407] %: связей % из % — места нет или парка нет в справочнике, сверить', r.slug, r.got, r.expected;
    ELSE
      RAISE NOTICE '[1407] %: связей %', r.slug, r.got;
    END IF;
  END LOOP;
END $$;

COMMIT;

